  const heelY = Math.max(
    vis(LM.R_HEEL) > 0.3 ? lms[LM.R_HEEL].y : 0,
    vis(LM.L_HEEL) > 0.3 ? lms[LM.L_HEEL].y : 0);
  if (heelY > 0.985) return { ok: false, reason: 'feet_cut' };
  return { ok: true };
