  const legLen = (Math.hypot(lh.x - la.x, lh.y - la.y) +
                  Math.hypot(rh.x - ra.x, rh.y - ra.y)) / 2;
  if (legLen < 1e-3) return false;
  return Math.abs(la.y - ra.y) / legLen > 0.12;
