    const [k, a, h] = side === 'R'
      ? [LM.R_KNEE, LM.R_ANKLE, LM.R_HEEL] : [LM.L_KNEE, LM.L_ANKLE, LM.L_HEEL];
    return vis(k) > 0.4 && vis(a) > 0.4 && vis(h) > 0.3;
